// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Батч-переключение стоп-листа
	// (POST /menu/availability)
	SetAvailability(w http.ResponseWriter, r *http.Request)
	// Импорт полного снапшота меню
	// (POST /menu/import)
	ImportMenu(w http.ResponseWriter, r *http.Request)
	// Лента заказов заведения
	// (GET /orders)
	ListVenueOrders(w http.ResponseWriter, r *http.Request, params ListVenueOrdersParams)
	// Карточка заказа
	// (GET /orders/{orderId})
	GetVenueOrder(w http.ResponseWriter, r *http.Request, orderId OrderId)
	// Принять заказ и назвать ETA
	// (POST /orders/{orderId}/accept)
	AcceptOrder(w http.ResponseWriter, r *http.Request, orderId OrderId)
	// Заказ доставлен
	// (POST /orders/{orderId}/delivered)
	MarkOrderDelivered(w http.ResponseWriter, r *http.Request, orderId OrderId)
	// Заказ готов к выдаче
	// (POST /orders/{orderId}/ready)
	MarkOrderReady(w http.ResponseWriter, r *http.Request, orderId OrderId)
	// Отклонить заказ
	// (POST /orders/{orderId}/reject)
	RejectOrder(w http.ResponseWriter, r *http.Request, orderId OrderId)
	// Настройки заведения
	// (PUT /venue)
	UpdateVenueSettings(w http.ResponseWriter, r *http.Request)
	// Витрина статистики заведения
	// (GET /venue/stats)
	GetVenueStats(w http.ResponseWriter, r *http.Request, params GetVenueStatsParams)
	// Куда платформе слать заказы
	// (PUT /webhook)
	RegisterWebhook(w http.ResponseWriter, r *http.Request)
}

