// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Батч-переключение стоп-листа
	// (POST /menu/availability)
	SetAvailability(ctx context.Context, request SetAvailabilityRequestObject) (SetAvailabilityResponseObject, error)
	// Импорт полного снапшота меню
	// (POST /menu/import)
	ImportMenu(ctx context.Context, request ImportMenuRequestObject) (ImportMenuResponseObject, error)
	// Лента заказов заведения
	// (GET /orders)
	ListVenueOrders(ctx context.Context, request ListVenueOrdersRequestObject) (ListVenueOrdersResponseObject, error)
	// Карточка заказа
	// (GET /orders/{orderId})
	GetVenueOrder(ctx context.Context, request GetVenueOrderRequestObject) (GetVenueOrderResponseObject, error)
	// Принять заказ и назвать ETA
	// (POST /orders/{orderId}/accept)
	AcceptOrder(ctx context.Context, request AcceptOrderRequestObject) (AcceptOrderResponseObject, error)
	// Заказ доставлен
	// (POST /orders/{orderId}/delivered)
	MarkOrderDelivered(ctx context.Context, request MarkOrderDeliveredRequestObject) (MarkOrderDeliveredResponseObject, error)
	// Заказ готов к выдаче
	// (POST /orders/{orderId}/ready)
	MarkOrderReady(ctx context.Context, request MarkOrderReadyRequestObject) (MarkOrderReadyResponseObject, error)
	// Отклонить заказ
	// (POST /orders/{orderId}/reject)
	RejectOrder(ctx context.Context, request RejectOrderRequestObject) (RejectOrderResponseObject, error)
	// Настройки заведения
	// (PUT /venue)
	UpdateVenueSettings(ctx context.Context, request UpdateVenueSettingsRequestObject) (UpdateVenueSettingsResponseObject, error)
	// Витрина статистики заведения
	// (GET /venue/stats)
	GetVenueStats(ctx context.Context, request GetVenueStatsRequestObject) (GetVenueStatsResponseObject, error)
	// Куда платформе слать заказы
	// (PUT /webhook)
	RegisterWebhook(ctx context.Context, request RegisterWebhookRequestObject) (RegisterWebhookResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

